import React from 'react';
import { Link } from 'react-router-dom';
import { FiMapPin } from 'react-icons/fi';

const ProductCard = ({ product }) => {
    const mainPhoto = product.photos && product.photos[0] ? `http://localhost:3001${product.photos[0]}` : null;

    const getCategoryIcon = (category) => {
        const icons = { telemovel: '📱', laptop: '💻', console: '🎮', tablet: '📟' };
        return icons[category] || '📦';
    };

    const getContactMethodIcon = (method) => {
        if (method === 'whatsapp') return '💚 WhatsApp';
        if (method === 'call') return '📞 Ligação';
        return '💚 WhatsApp / 📞 Ligação';
    };

    return (
        <Link to={`/product/${product.id}`} className="block">
            <div className="bg-white rounded-xl shadow-md overflow-hidden hover:shadow-xl transition-all duration-300 transform hover:-translate-y-1">
                <div className="relative h-48 bg-gray-100">
                    {mainPhoto ? (
                        <img src={mainPhoto} alt={product.title} className="w-full h-full object-cover" />
                    ) : (
                        <div className="w-full h-full flex items-center justify-center text-5xl">{getCategoryIcon(product.category)}</div>
                    )}
                    <span className={`absolute top-2 right-2 px-2 py-1 rounded-full text-xs font-semibold ${product.condition === 'novo' ? 'bg-green-100 text-green-600' : 'bg-yellow-100 text-yellow-600'}`}>
                        {product.condition === 'novo' ? 'Novo' : 'Semi-novo'}
                    </span>
                </div>
                <div className="p-4">
                    <h3 className="font-semibold text-gray-800 mb-1 line-clamp-2">{product.title}</h3>
                    <p className="text-xl font-bold text-primary-600 mb-2">{product.price.toLocaleString()} Kz</p>
                    <div className="flex items-center justify-between text-sm text-gray-500">
                        <div className="flex items-center"><FiMapPin className="mr-1" size={14} /><span>{product.location}</span></div>
                        <span>{product.sellerName}</span>
                    </div>
                    <div className="text-xs text-gray-400 mt-2 flex items-center justify-between">
                        <span>📞 {getContactMethodIcon(product.contactMethod)}</span>
                        <span>👁️ {product.views || 0} visualizações</span>
                    </div>
                </div>
            </div>
        </Link>
    );
};

export default ProductCard;
